  fig_coeff.suptitle(f"Coeficiente IC 95% [9 threads; 300000 max prime]", fontsize=16, fontweight="bold")
  fig_coeff.legend(loc="upper right")

  fig_mean, ax_mean = plt.subplots(figsize=(16, 9))
  ax_mean.set_ylabel("seconds")
  ax_mean.yaxis.set_label_position("left")
  ax_mean.yaxis.set_ticks_position("left")
  ax_mean.set_xticks(range(labels[0], labels[-1] + 1, 1))
  ax_mean.plot(labels, mean, label="response time")
  ax_mean.axhline(y=np.mean(mean), color="red", linestyle="--", linewidth=2, label="mean")
  fig_mean.suptitle(f"RT [9 threads; 300000 max prime]", fontsize=16, fontweight="bold")
  fig_mean.legend(loc="upper right")

  plt.show()
